<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import RaceHistoryFields from '../components/RaceHistoryFields.vue';
import { version as consentVersion } from '../../../shared/legal-documents.json';

const route=useRoute(),router=useRouter(),base=import.meta.env.BASE_URL.replace(/\/$/,'');
const tokenNow=()=>localStorage.getItem('marathon_token')||'';
let activeToken=tokenNow(),disposed=false,sequence=0,sessionEpoch=0;const controllers=new Set();
const loggedIn=ref(Boolean(activeToken)),data=ref(null),detail=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const reading=ref('growth'),year=ref(''),search=ref(''),importText=ref(''),candidates=ref([]),importError=ref(''),progress=ref('');
const editorDialog=ref(null),consentDialog=ref(null),deleteDialog=ref(null),editId=ref(''),editor=ref(emptyDraft()),editorError=ref(''),pendingImages=ref([]),uploadKind=ref('photo'),deleteTarget=ref(null),deleteError=ref('');
let pendingImageToken='',noticeTimer;
const meaningTags=['第一次','突破','陪伴','归来','城市','坚持','享受比赛'];
const mediaKinds=[{value:'photo',label:'比赛照片'},{value:'certificate',label:'完赛证书'},{value:'medal',label:'奖牌照片'},{value:'bib',label:'号码布'},{value:'route',label:'路线图'},{value:'shirt',label:'参赛服'}];
const today=computed(()=>data.value?.asOf||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}));
const importMode=computed(()=>route.query.import==='1'),entries=computed(()=>data.value?.entries||[]),selectedEntry=computed(()=>detail.value?.entry||null);
const years=computed(()=>[...new Set(entries.value.map(x=>x.raceDate?.slice(0,4)).filter(Boolean))].sort().reverse());
const filteredEntries=computed(()=>entries.value.filter(x=>(!year.value||x.raceDate?.startsWith(year.value))&&(!search.value.trim()||(x.name+' '+x.city).toLowerCase().includes(search.value.trim().toLowerCase()))));
const highlight=computed(()=>entries.value.find(x=>x.isPb&&x.improvementSeconds>0)||entries.value.find(x=>x.isPb)||entries.value[0]);
const growthNodes=computed(()=>{const nodes={},seen=new Set(),ordered=[...entries.value].sort((a,b)=>a.raceDate.localeCompare(b.raceDate)||a.id.localeCompare(b.id));for(const [index,item]of ordered.entries()){if(index===0)nodes[item.id]='这份跑史的起点';if(item.status==='finished'&&item.kind==='road'&&item.meet==='offline'&&!seen.has(item.distance)){seen.add(item.distance);if(!nodes[item.id]&&['full','half'].includes(item.distance))nodes[item.id]='已记录首场'+distanceLabel(item.distance);}if(item.improvementSeconds>0)nodes[item.id]='同口径进步 '+difference(item.improvementSeconds);}return nodes;});
const selectedCandidates=computed(()=>candidates.value.filter(x=>x._selected&&!x.duplicateId));
const unconfirmedCount=computed(()=>selectedCandidates.value.filter(x=>!x._confirmed).length);
const invalidProjectCount=computed(()=>selectedCandidates.value.filter(x=>!canonicalDistance(x.distance)).length);
const clock=seconds=>seconds==null||!Number.isFinite(Number(seconds))?'':`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
function emptyDraft(){return{name:'',raceDate:'',city:'',province:'',distance:'full',kind:'road',meet:'offline',status:'finished',timing:'net',netTime:'',gunTime:'',unknownTime:'',bib:'',story:'',tags:[]};}
function canonicalDistance(value){return ['full','half','10k','5k','other'].includes(value)?value:'';}
function toDraft(value){return{...emptyDraft(),...value,distance:canonicalDistance(value.distance),distanceText:value.distanceText||(!canonicalDistance(value.distance)?String(value.distance||''):''),tags:[...(value.tags||[])],netTime:value.netTime||clock(value.netSeconds),gunTime:value.gunTime||clock(value.gunSeconds),unknownTime:value.unknownTime||(value.timing==='unknown'?clock(value.unknownSeconds??value.seconds):''),_key:crypto.randomUUID?.()||Math.random().toString(36),_selected:!value.duplicateId,_confirmed:false};}
function timeSeconds(value){if(!value?.trim())return null;const m=value.trim().match(/^(\d{1,2}):([0-5]\d):([0-5]\d)$/);if(!m)throw new Error('用时请填写为 时:分:秒，例如 03:45:00');return Number(m[1])*3600+Number(m[2])*60+Number(m[3]);}
function payload(value){const finished=value.status==='finished',net=finished?timeSeconds(value.netTime):null,gun=finished?timeSeconds(value.gunTime):null,unknown=finished?timeSeconds(value.unknownTime):null;if(!value.name?.trim()||!value.raceDate)throw new Error('请补全比赛名称和日期');if(!canonicalDistance(value.distance))throw new Error('请确认比赛项目');if(net&&gun&&net>gun)throw new Error('净计时不应大于枪声时间，请核对原资料');return{name:value.name.trim(),raceDate:value.raceDate,city:value.city||'',province:value.province||'',distance:value.distance,kind:value.kind,meet:value.meet,status:value.status,timing:value.status==='finished'&&!net&&!gun&&!unknown?'unknown':value.timing,netTime:value.status==='finished'?value.netTime:'',gunTime:value.status==='finished'?value.gunTime:'',unknownTime:value.status==='finished'&&value.timing==='unknown'?value.unknownTime:'',seconds:value.status==='finished'&&value.timing==='unknown'?unknown:null,bib:value.bib||'',story:value.story||'',tags:value.tags||[],raceId:value.raceId||'',sourceKey:value.sourceKey,source:value.source,confirmed:true};}
function resetPrivate(){sessionEpoch++;sequence++;controllers.forEach(c=>c.abort());controllers.clear();data.value=null;detail.value=null;reading.value='growth';year.value='';search.value='';editId.value='';editorError.value='';deleteError.value='';uploadKind.value='photo';candidates.value=[];importText.value='';pendingImages.value=[];pendingImageToken='';editor.value=emptyDraft();deleteTarget.value=null;notice.value='';error.value='';importError.value='';progress.value='';loading.value=false;busy.value=false;[editorDialog,consentDialog,deleteDialog].forEach(d=>d.value?.close());}
function sessionCurrent(session,epoch){return!disposed&&session===activeToken&&session===tokenNow()&&epoch===sessionEpoch;}
function checkSession(){const token=tokenNow();if(token!==activeToken){resetPrivate();activeToken=token;loggedIn.value=Boolean(token);return false;}return !disposed&&Boolean(token);}
async function request(path,options={}){if(!checkSession())throw new Error('登录状态已变化，请重新加载后再操作');const session=activeToken,epoch=sessionEpoch,controller=new AbortController();controllers.add(controller);try{const headers={Authorization:'Bearer '+session,...options.headers};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(base+'/api/me/race-history'+path,{...options,headers,signal:controller.signal});const result=await response.json().catch(()=>({}));if(!sessionCurrent(session,epoch)){checkSession();throw new Error('登录状态已变化，本次操作已结束');}if(!response.ok){if(response.status===401){resetPrivate();loggedIn.value=false;}throw new Error(result.error||'没有处理成功，请重试');}return result;}finally{controllers.delete(controller);}}
async function load(){if(!checkSession()&&!loggedIn.value)return;const id=++sequence;loading.value=true;error.value='';try{const result=await request('');if(id!==sequence)return;data.value=result;if(route.query.race)await fetchDetail(String(route.query.race));}catch(e){if(id===sequence&&e.name!=='AbortError')error.value=e.message;}finally{if(id===sequence)loading.value=false;}}
async function fetchDetail(id){const session=activeToken,epoch=sessionEpoch;detail.value=null;try{const result=await request('/'+encodeURIComponent(id));if(sessionCurrent(session,epoch)&&route.query.race===id)detail.value=result;}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')error.value=e.message;}}
function login(){localStorage.setItem('marathon_return_after_login','/history');router.push('/mine');}
function showHistory(){if(busy.value)return;detail.value=null;router.replace({path:'/history'});}
function showImport(){if(busy.value)return;detail.value=null;router.replace({path:'/history',query:{import:'1'}});}
function openEntry(id){if(busy.value)return;error.value='';router.push({path:'/history',query:{race:id}});}
watch(()=>route.query.race,(id)=>{if(id&&loggedIn.value)fetchDetail(String(id));else detail.value=null;});
watch(notice,value=>{clearTimeout(noticeTimer);if(value)noticeTimer=setTimeout(()=>notice.value='',5500);});
function flash(message){notice.value=message;}
function openEditor(value){if(!checkSession())return;editorError.value='';editId.value=value?.id||'';editor.value=value?toDraft(value):emptyDraft();editorDialog.value.showModal();}
function toggleTag(tag){const list=editor.value.tags;editor.value.tags=list.includes(tag)?list.filter(x=>x!==tag):[...list,tag];}
async function saveEntry(){if(busy.value||!checkSession())return;editorError.value='';let body;try{body=payload(editor.value);}catch(e){editorError.value=e.message;return;}const session=activeToken,epoch=sessionEpoch;busy.value=true;try{const value=await request(editId.value?'/'+encodeURIComponent(editId.value):'',{method:editId.value?'PATCH':'POST',body:JSON.stringify(body)});if(!sessionCurrent(session,epoch))return;editorDialog.value.close();await load();if(!sessionCurrent(session,epoch))return;if(value.entry?.id){await router.replace({path:'/history',query:{race:value.entry.id}});if(!sessionCurrent(session,epoch))return;await fetchDetail(value.entry.id);}if(sessionCurrent(session,epoch))flash('这场经历已保存。');}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')editorError.value=e.message;}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
function imageError(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))return'请选择 JPG、PNG 或 WebP 图片';if(file.size>8*1024*1024)return'每张图片不超过 8 MB';return'';}
function chooseImages(event){if(!checkSession())return;const files=[...event.target.files];event.target.value='';if(!files.length)return;if(files.length>20){importError.value='一次最多选择 20 张图片';return;}for(const file of files){const message=imageError(file);if(message){importError.value=message;return;}}importError.value='';pendingImages.value=files;pendingImageToken=activeToken;consentDialog.value.showModal();}
function cancelRecognition(){consentDialog.value?.close();pendingImages.value=[];pendingImageToken='';}
async function recognizeImages(){if(busy.value||!checkSession()||pendingImageToken!==activeToken){cancelRecognition();return;}const session=activeToken,epoch=sessionEpoch,files=[...pendingImages.value];cancelRecognition();busy.value=true;importError.value='';const outputs=[];try{for(let i=0;i<files.length;i++){if(!sessionCurrent(session,epoch))return;progress.value=`正在识别第 ${i+1} / ${files.length} 张，稍等片刻…`;const body=new FormData();body.append('file',files[i]);const result=await request('/recognize',{method:'POST',body,headers:{'X-Race-History-Consent':consentVersion}});if(!sessionCurrent(session,epoch))return;if(result.text?.trim())outputs.push(result.text.trim());else importError.value=`第 ${i+1} 张未识别出文字，可以换一张清晰图片或手动填写。`;if(result.warnings?.length)importError.value=result.warnings.join('；');}if(sessionCurrent(session,epoch)&&outputs.length){importText.value=[importText.value.trim(),...outputs].filter(Boolean).join('\n\n');progress.value='识别文字已放入下方，可先更正，再点“识别并核对比赛”。';}}catch(e){if(!sessionCurrent(session,epoch))return;if(e.name!=='AbortError')importError.value=e.message;if(outputs.length)importText.value=[importText.value.trim(),...outputs].filter(Boolean).join('\n\n');progress.value='';}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
async function chooseTextFile(event){if(!checkSession())return;const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>512*1024){importError.value='成绩表不超过 512 KB';return;}const session=activeToken,epoch=sessionEpoch;try{const text=await file.text();if(sessionCurrent(session,epoch)){importText.value=text;importError.value='';}}catch{if(sessionCurrent(session,epoch))importError.value='无法读取这份文件，请重试或直接粘贴内容。';}}
async function previewImport(){if(busy.value||!checkSession())return;const session=activeToken,epoch=sessionEpoch;busy.value=true;importError.value='';try{const value=await request('/import/preview',{method:'POST',body:JSON.stringify({text:importText.value})});if(!sessionCurrent(session,epoch))return;candidates.value=(value.candidates||[]).map(toDraft);if(value.warnings?.length)importError.value=value.warnings.join('；');if(!candidates.value.length)importError.value='暂未识别到比赛，可补充文字或手动记一场。';else flash(`已整理出 ${candidates.value.length} 条候选，请核对后再保存。`);}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')importError.value=e.message;}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
async function confirmImport(){if(busy.value||!selectedCandidates.value.length||!checkSession())return;if(invalidProjectCount.value){importError.value='请先确认所选比赛的项目，再核对保存';return;}if(unconfirmedCount.value)return;let values;try{values=selectedCandidates.value.map(payload);}catch(e){importError.value=e.message;return;}const session=activeToken,epoch=sessionEpoch;busy.value=true;importError.value='';try{const result=await request('/import/confirm',{method:'POST',body:JSON.stringify({candidates:values})});if(!sessionCurrent(session,epoch))return;candidates.value=[];importText.value='';progress.value='';await load();if(!sessionCurrent(session,epoch))return;await router.replace('/history');if(sessionCurrent(session,epoch))flash(`已加入 ${result.created||0} 场比赛${result.skipped?`，${result.skipped} 条已有或曾删除的记录未重复加入`:''}。`);}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')importError.value=e.message;}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
function mediaUrl(media){const value=media?.url||'';if(!value)return'';if(!value.startsWith(base+'/api/')&&!value.startsWith('/api/'))return'';return value+(value.includes('?')?'&':'?')+'t='+encodeURIComponent(activeToken);}
function isVideo(media){return media.kind==='video'||String(media.mime||'').startsWith('video/');}
function coverOf(entry){const media=entry?.media||[];return media.find(x=>x.id===entry.coverMediaId&&x.kind==='photo'&&!isVideo(x))||media.find(x=>x.kind==='photo'&&!isVideo(x));}
function hideBrokenImage(event){event.target.style.display='none';}
async function addMedia(event){const file=event.target.files[0];event.target.value='';if(!file||busy.value||!checkSession()||!selectedEntry.value)return;const validation=imageError(file);if(validation){error.value=validation;return;}const session=activeToken,epoch=sessionEpoch,id=selectedEntry.value.id;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file);await request('/'+encodeURIComponent(id)+'/media?kind='+uploadKind.value,{method:'POST',body});if(!sessionCurrent(session,epoch))return;await load();if(!sessionCurrent(session,epoch))return;await fetchDetail(id);if(sessionCurrent(session,epoch))flash('图片已保存到这场经历，仅自己可见。');}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')error.value=e.message;}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
async function setCover(media){if(busy.value||!checkSession())return;const session=activeToken,epoch=sessionEpoch,id=selectedEntry.value.id;busy.value=true;try{const value=await request('/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({coverMediaId:media.id})});if(!sessionCurrent(session,epoch))return;detail.value=value;await load();if(sessionCurrent(session,epoch))flash('代表照片已更新。');}catch(e){if(sessionCurrent(session,epoch)&&e.name!=='AbortError')error.value=e.message;}finally{if(sessionCurrent(session,epoch))busy.value=false;}}
function requestDeleteEntry(){deleteTarget.value={entryId:selectedEntry.value.id,legacy:selectedEntry.value.id.startsWith('result:')};deleteError.value='';deleteDialog.value.showModal();}
function requestDeleteMedia(media){deleteTarget.value={entryId:selectedEntry.value.id,media};deleteError.value='';deleteDialog.value.showModal();}
