function distanceLabel(value){return{full:'全马',half:'半马','10k':'10 公里','5k':'5 公里',other:'其他项目'}[value]||value;}
function statusLabel(value){return{finished:'已完赛',dnf:'未完赛',dns:'未出发'}[value]||'参赛经历';}
function timingLabel(value){return{net:'净计时',gun:'枪声时间',unknown:'用时 · 口径待补充'}[value.timing]||'用时';}
function mediaKindLabel(value){return value==='video'?'比赛视频':mediaKinds.find(x=>x.value===value)?.label||'比赛资料';}
function difference(value){const sec=Math.round(value);return`${Math.floor(sec/60)}′${String(sec%60).padStart(2,'0')}″`;}
function entryHeadline(value){if(value.status==='dnf')return'这段经历，同样值得留下。';if(value.status==='dns')return'这场计划，也是一段跑步记忆。';if(value.isPb)return'在已记录的比赛中，又一次向前。';return'每一次出发，都成为自己的一部分。';}
function saveDownload(content,mime,name){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRow(entry){return{name:entry.name,raceDate:entry.raceDate,city:entry.city,province:entry.province,distance:entry.distance,kind:entry.kind,meet:entry.meet,status:entry.status,timing:entry.timing,netTime:clock(entry.netSeconds),gunTime:clock(entry.gunSeconds),unknownTime:entry.timing==='unknown'?clock(entry.seconds):'',bib:entry.bib,story:entry.story,tags:entry.tags,source:entry.source,sourceKey:entry.sourceKey};}
const csvCell=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
function exportHistory(type){if(!checkSession())return;const rows=entries.value.map(exportRow);if(type==='json')saveDownload(JSON.stringify(rows,null,2),'application/json;charset=utf-8','我的跑史.json');else{const keys=['name','raceDate','city','province','distance','kind','meet','status','timing','netTime','gunTime','unknownTime','bib','story','tags','sourceKey'];saveDownload('\uFEFF'+[keys.join(','),...rows.map(row=>keys.map(key=>csvCell(Array.isArray(row[key])?row[key].join('、'):row[key])).join(','))].join('\r\n'),'text/csv;charset=utf-8','我的跑史.csv');}}
function downloadTemplate(){saveDownload('\uFEFF比赛名称,日期,项目,净计时,枪声时间,城市\r\n','text/csv;charset=utf-8','跑史导入模板.csv');}
function exportReview(){if(!checkSession())return;const entry=selectedEntry.value,review=detail.value.review;const content=[entry.name,`${entry.raceDate} · ${entry.distanceLabel} · ${statusLabel(entry.status)}`,`${timingLabel(entry)}：${entry.clock}`,review?.headline,...(review?.facts||[]),entry.story?'我的感受：'+entry.story:'',entry.tags?.length?'这场的意义：'+entry.tags.join('、'):'',review?.scope,'来源：'+(entry.source?.label||'个人记录')+' · 尚未官方核验'].filter(Boolean).join('\n\n');saveDownload(content,'text/plain;charset=utf-8',entry.name+'-我的回顾.txt');}
function onSessionEvent(){if(!checkSession()&&loggedIn.value)load();}
onMounted(()=>{load();window.addEventListener('storage',onSessionEvent);window.addEventListener('focus',onSessionEvent);});
onBeforeUnmount(()=>{disposed=true;resetPrivate();clearTimeout(noticeTimer);window.removeEventListener('storage',onSessionEvent);window.removeEventListener('focus',onSessionEvent);});
</script>

